32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
109	        if (owner.getRegistrationDate() == null) {
110	            owner.setRegistrationDate(LocalDate.now());
111	        }
112	        if (isDuplicateTelephone(owner)) {
113	            throw new DuplicateOwnerException("An owner with telephone "
114	                + owner.getTelephone() + " already exists");
115	        }
116	        if (isDuplicateEmail(owner)) {
117	            throw new DuplicateOwnerException("An owner with email "
118	                + owner.getEmail() + " already exists");
119	        }
120	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
121	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
122	        this.clinicService.saveOwner(owner);
123	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
124	        headers.setLocation(UriComponentsBuilder.newInstance()
125	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
126	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
127	    }
128	
129	    /**
130	     * Determines whether any other owner already uses the candidate's telephone number.
131	     * The comparison ignores letter case and surrounding or repeated whitespace.
132	     *
133	     * @param candidate the owner about to be created
134	     * @return {@code true} if an owner with the same telephone is already present in the data store
135	     */
136	    private boolean isDuplicateTelephone(Owner candidate) {
137	        String telephone = normalizeTelephone(candidate.getTelephone());
138	        return this.clinicService.findAllOwners().stream()
139	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
140	    }
141	
142	    /**
143	     * Canonicalises a telephone number by stripping every character that is not a digit
144	     * (for example spaces, dashes and parentheses), so that {@code "(613) 555-0100"} and
145	     * {@code "6135550100"} are treated as the same number. This is the form persisted for
146	     * an owner and used for the telephone-uniqueness check.
147	     *
148	     * @param telephone the raw telephone value, possibly {@code null}
149	     * @return the digits-only telephone, or {@code null} if {@code telephone} was {@code null}
150	     */
151	    private static String normalizeTelephone(String telephone) {
152	        if (telephone == null) {
153	            return null;
154	        }
155	        return telephone.replaceAll("[^0-9]", "");
156	    }
157	
158	    /**
159	     * Determines whether any other owner already uses the candidate's email address.
160	     * An absent or blank email is never considered a duplicate. The comparison ignores
161	     * letter case and surrounding or repeated whitespace.
162	     *
163	     * @param candidate the owner about to be created
164	     * @return {@code true} if an owner with the same email is already present in the data store
165	     */
166	    private boolean isDuplicateEmail(Owner candidate) {
167	        String email = normalize(candidate.getEmail());
168	        if (email == null || email.isBlank()) {
169	            return false;
170	        }
171	        return this.clinicService.findAllOwners().stream()
172	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
173	    }
174	
175	    /**
176	     * Builds the customer code for a newly created owner, formatted as
177	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
178	     * owners already present in the same city, zero-padded to four digits
179	     * (e.g. {@code 'LONDON-0007'}). Cities are matched ignoring letter case.
180	     *
181	     * @param city the city of the owner about to be created
182	     * @return the formatted customer code
183	     */
184	    private String nextCustomerCode(String city) {
185	        long ownersInCity = this.clinicService.findAllOwners().stream()
186	            .filter(existing -> existing.getCity() != null
187	                && existing.getCity().equalsIgnoreCase(city))
188	            .count();
189	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
190	    }
191	
192	    /**
193	     * Canonicalises a value for duplicate detection so that comparisons ignore letter
194	     * case and surrounding or repeated whitespace. Surrounding whitespace is stripped,
195	     * any run of internal whitespace is collapsed to a single space, and the result is
196	     * lower-cased. For example {@code "  john   smith "} and {@code "John Smith"} both
197	     * normalise to {@code "john smith"}.
198	     *
199	     * @param value the raw value, possibly {@code null}
200	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
201	     */
202	    private static String normalize(String value) {
203	        if (value == null) {
204	            return null;
205	        }
206	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
212	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
213	        if (currentOwner == null) {
214	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	        }
216	        currentOwner.setAddress(ownerFieldsDto.getAddress());
217	        currentOwner.setCity(ownerFieldsDto.getCity());
218	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
219	        currentOwner.setLastName(ownerFieldsDto.getLastName());
220	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
221	        this.clinicService.saveOwner(currentOwner);
222	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
223	    }
224	
225	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
226	    @Transactional
227	    @Override
228	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
229	        Owner owner = this.clinicService.findOwnerById(ownerId);
230	        if (owner == null) {
231	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	        }
233	        this.clinicService.deleteOwner(owner);
234	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
235	    }
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Override
239	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
240	        Owner owner = this.clinicService.findOwnerById(ownerId);
241	        if (owner == null) {
242	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
243	        }
244	        HttpHeaders headers = new HttpHeaders();
245	        Pet pet = petMapper.toPet(petFieldsDto);
246	        owner.setId(ownerId);
247	        pet.setOwner(owner);
248	        pet.getType().setName(null);
249	        this.clinicService.savePet(pet);
250	        PetDto petDto = petMapper.toPetDto(pet);
251	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
252	            .buildAndExpand(pet.getId()).toUri());
253	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
254	    }
255	
256	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
257	    @Override
258	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
259	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
260	        if (currentOwner != null) {
261	            Pet currentPet = this.clinicService.findPetById(petId);
262	            if (currentPet != null) {
263	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
264	                currentPet.setName(petFieldsDto.getName());
265	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
266	                this.clinicService.savePet(currentPet);
267	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
268	            }
269	        }
270	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
271	    }
272	
273	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
274	    @Override
275	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
276	        HttpHeaders headers = new HttpHeaders();
277	        Visit visit = visitMapper.toVisit(visitFieldsDto);
278	        Pet pet = new Pet();
279	        pet.setId(petId);
280	        visit.setPet(pet);
281	        this.clinicService.saveVisit(visit);
282	        VisitDto visitDto = visitMapper.toVisitDto(visit);
283	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
284	            .buildAndExpand(visit.getId()).toUri());
285	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
286	    }
287	
288	
289	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
290	    @Override
291	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
292	        Owner owner = this.clinicService.findOwnerById(ownerId);
293	        if (owner != null) {
294	            Pet pet = owner.getPet(petId);
295	            if (pet != null) {
296	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
297	            }
298	        }
299	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
300	    }
301	}
