1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(toDisplayName(owner))")
22	    @Mapping(target = "initials", expression = "java(toInitials(owner))")
23	    OwnerDto toOwnerDto(Owner owner);
24	
25	    /**
26	     * Computes the display name of an owner formatted as {@code 'LastName, FirstName'}.
27	     *
28	     * @param owner the owner, may be {@code null}
29	     * @return the formatted display name, or {@code null} if {@code owner} is {@code null}
30	     */
31	    default String toDisplayName(Owner owner) {
32	        if (owner == null) {
33	            return null;
34	        }
35	        return owner.getLastName() + ", " + owner.getFirstName();
36	    }
37	
38	    /**
39	     * Computes the initials of an owner formatted as the upper-cased first letters of the
40	     * first and last name, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
41	     *
42	     * @param owner the owner, may be {@code null}
43	     * @return the formatted initials, or {@code null} if {@code owner} is {@code null}
44	     */
45	    default String toInitials(Owner owner) {
46	        if (owner == null) {
47	            return null;
48	        }
49	        return initial(owner.getFirstName()) + initial(owner.getLastName());
50	    }
51	
52	    private static String initial(String name) {
53	        if (name == null || name.isEmpty()) {
54	            return "";
55	        }
56	        return Character.toUpperCase(name.charAt(0)) + ".";
57	    }
58	
59	    Owner toOwner(OwnerDto ownerDto);
60	
61	    @Mapping(target = "id", ignore = true)
62	    @Mapping(target = "pets", ignore = true)
63	    Owner toOwner(OwnerFieldsDto ownerDto);
64	
65	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
66	
67	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
68	
69	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
70	        OwnerPageDto ownerPageDto = new OwnerPageDto();
71	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
72	        ownerPageDto.setPage(ownerPage.getNumber());
73	        ownerPageDto.setSize(ownerPage.getSize());
74	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
75	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
76	        return ownerPageDto;
77	    }
78	}
